const event = $input.all()[0].json || {};
const command = event.input || event.command || event.commands || '';

const urlRegex = /(https?:\/\/[^\s]+)/g;
const urls = command.match(urlRegex) || [];

const domainRegex = /(?:https?:\/\/)?([\w\-]+\.[\w\-\.]+)/g;
const domains = Array.from(command.matchAll(domainRegex), (m) => m[1]);

// Grupo 13: la tabla de tiers vive en "Calcular Risk Score"; aquí solo
// se preservan los IoCs y el event_id para que PB-H2 actualice (no duplique)
// la fila ya insertada por PB-H1.
const dangerousCommands = ['rm -rf', 'chmod 777', 'nc -e', 'wget', 'curl', 'python -c', 'bash -i'];
const isDangerous = dangerousCommands.some(dc => command.toLowerCase().includes(dc));

const ip = event.src_ip || event.source_ip || '';
const valid = /^(\d{1,3}\.){3}\d{1,3}$/.test(ip) && ip.split('.').every(n => +n >= 0 && +n <= 255);

return [{
  json: {
    timestamp: event.timestamp || new Date().toISOString(),
    source_honeypot: 'cowrie',
    src_ip: valid ? ip : '0.0.0.0',
    dst_port: event.dst_port || event.port || null,
    protocol: event.protocol || 'ssh',
    username: event.username || null,
    session_id: event.session || event.session_id,
    commands: command,
    extracted_urls: urls,
    extracted_domains: domains,
    is_dangerous_command: isDangerous,
    playbook_id: 'PB-H2-v1.0',
    att_ck_technique: 'T1059',
    event_id: event.event_id || event.id || null,
    enrichment_data: {},
    raw_data: event
  }
}];

// Hardening #5 (Opción A): divide extracted_domains en items {domain}
// para que "VirusTotal Lookup" consulte /api/v3/domains/<domain> por IoC.
// Cada item derivado conserva los campos base del evento.
const out = [];
for (const item of $input.all()) {
  const base = item.json || {};
  const raw = Array.isArray(base.extracted_domains) ? base.extracted_domains : [];
  const unique = [...new Set(raw.filter(d => typeof d === 'string' && d.trim().length > 0))].map(d => d.trim());
  for (const domain of unique) {
    out.push({ json: { ...base, domain } });
  }
}
return out;

// Calcular score de riesgo para comandos (grupo 13: tabla de tiers)
// Referencias a nodos de enriquecimiento (VirusTotal/WHOIS) con fallback
// base: evento limpio desde Extraer IOCs (robusto aunque el enriquecimiento falle)
const baseItems = $('Extraer IOCs').all() || [];
const base = (baseItems[0] && baseItems[0].json) ? baseItems[0].json : (($input.all()[0] && $input.all()[0].json) || {});
let vtItems = [];
try { vtItems = $('VirusTotal Lookup').all() || []; } catch (e) { vtItems = []; }
let whoisItems = [];
try { whoisItems = $('WHOIS Domain').all() || []; } catch (e) { whoisItems = []; }

const vtData = (vtItems[0] && vtItems[0].json && vtItems[0].json.data) || {};
const whoisData = (whoisItems[0] && whoisItems[0].json) || {};

// ---------------------------------------------------------------------------
// Tabla de tiers de riesgo por contenido del comando (grupo 13)
// CRITICAL (base 0.85): destruccion de datos (rm -rf, mkfs, dd), shell inversa
//   (bash -i >& | /dev/tcp | nc -e), pipe-a-shell (wget/curl | sh),
//   escalada/persistencia (passwd, useradd, ssh-keygen, crontab) y apagado.
// HIGH (base 0.70): descargas (wget/curl/scp), instalacion de paquetes,
//   netcat, kill de procesos, lectura de archivos sensibles (/etc/*) y
//   anti-forense (history -c, shred).
// MEDIUM (base 0.40): enumeracion y reconocimiento benigno (whoami, id, ls...).
// Sin match -> 0 (el enriquecimiento VT/WHOIS puede sumar aparte).
// Cada hit adicional dentro del tier suma "step", con techo "cap".
// Los buckets de severidad de la API quedan: <0.33 low, <0.66 medium,
// <0.85 high, >=0.85 critical.
// ---------------------------------------------------------------------------
const COMMAND_TIERS = [
  {
    base: 0.85, step: 0.05, cap: 1.0,
    patterns: [
      /rm\s+-[a-z]*r[a-z]*f/, /rm\s+-[a-z]*f[a-z]*r/, /--no-preserve-root/,
      /\bmkfs\b/, /\bdd\s+if=/, />\s*\/dev\/(sd[a-z]|nvme|hd[a-z])\b/,
      /:\(\)\s*\{.*\}\s*;/,
      /bash\s+-i\s+>&/, /\/dev\/tcp\//,
      /\bnc(at)?\b[^|;&]*\s-e\b/,
      /\|\s*(ba|z|da|k)?sh\b/,
      /chmod\s+777\s+\//, /\bchown\b[^;&]*\s+\//,
      /[>]{1,2}\s*\/etc\/(shadow|sudoers|passwd)\b/, /\bvisudo\b/, /\bchpasswd\b/,
      /(?<!\/)\bpasswd\b/, /\buseradd\b/, /\badduser\b/, /\busermod\b/,
      /\bssh-keygen\b/, /authorized_keys/,
      /\bcrontab\b(?!\s+-l\b)/, /\/etc\/rc\.local/, /systemctl\s+enable/,
      /\bshutdown\b/, /\breboot\b/, /\bhalt\b/, /\binit\s+[06]\b/
    ]
  },
  {
    base: 0.70, step: 0.04, cap: 0.84,
    patterns: [
      /\bwget\b/, /\bcurl\b/, /\bscp\b/, /\btftp\b/,
      /\bapt(-get)?\s+install\b/, /\byum\s+install\b/, /\bdnf\s+install\b/,
      /\bpacman\s+-[su]\b/, /\bpip3?\s+install\b/, /\bapk\s+add\b/,
      /\bnc(at)?\b/, /\bnetcat\b/,
      /\bkill(all)?\b/, /\bpkill\b/,
      /\b(cat|less|more|head|tail|strings)\s+\/etc\//, /\/etc\/passwd/, /\/etc\/shadow\b/, /\/etc\/sudoers\b/,
      /\bhistory\s+-c\b/, /unset\s+histfile/, /\bshred\b/, /\bwipe\b/,
      /\bgcc\b/, /\bmake\b/
    ]
  },
  {
    base: 0.40, step: 0.03, cap: 0.60,
    patterns: [
      /\bwhoami\b/, /\bid\b/, /\buname\b/, /\bhostname\b/, /\buptime\b/,
      /\bps\b/, /\bls\b/, /\bpwd\b/, /\benv\b/, /\bprintenv\b/,
      /\bcat\b/, /\bfind\b/, /\bgrep\b/, /\bdiff\b/, /\bfile\b/,
      /\bnmap\b/, /\bping\b/, /\bnslookup\b/, /\bdig\b/, /\btraceroute\b/,
      /\bnetstat\b/, /\bss\b/, /\barp\b/, /\broute\b/, /\bifconfig\b/, /\bip\s+addr\b/,
      /\becho\b/, /\bprintf\b/, /\bsleep\b/, /\bcd\b/, /\bmkdir\b/, /\btouch\b/
    ]
  }
];

function commandRiskScore(rawCommand) {
  const cmd = String(rawCommand || '').toLowerCase();
  if (!cmd.trim()) return 0;
  let best = 0;
  for (const tier of COMMAND_TIERS) {
    let hits = 0;
    for (const re of tier.patterns) {
      if (re.test(cmd)) hits += 1;
    }
    if (hits > 0) {
      const tierScore = Math.min(tier.base + (hits - 1) * tier.step, tier.cap);
      if (tierScore > best) best = tierScore;
    }
  }
  return best;
}

// El puntaje del comando es la base (garantiza el piso del tier);
// el enriquecimiento externo suma encima, con techo 1.0.
let score = commandRiskScore(base.commands);

// Score por detecciones en VirusTotal
const vtDetections = vtData.attributes?.last_analysis_stats?.malicious || 0;
if (vtDetections > 5) score += 0.4;
if (vtDetections > 10) score += 0.2;

// Score por dominio reciente (< 30 dias)
const domainAge = whoisData.create_date || whoisData.created_date || whoisData.createDate || '';
let domainAgeDays = 'N/A';
if (domainAge) {
  const created = new Date(domainAge);
  const daysOld = (new Date() - created) / (1000 * 60 * 60 * 24);
  domainAgeDays = daysOld.toFixed(0);
  if (daysOld < 30) score += 0.3;
}

// Score por multiples URLs
if ((base.extracted_urls || []).length > 2) score += 0.2;

score = Math.min(Number(score.toFixed(2)), 1);

const tier = score >= 0.85 ? 'critical' : (score >= 0.66 ? 'high' : (score >= 0.33 ? 'medium' : 'low'));
const prevEnrichment = (base.enrichment_data && typeof base.enrichment_data === 'object' && !Array.isArray(base.enrichment_data)) ? base.enrichment_data : {};
const enrichmentTimestamp = new Date().toISOString();

return [{
  json: {
    ...base,
    risk_score: score,
    command_risk_tier: tier,
    // El UPDATE de PostgreSQL Auditoria persiste este objeto como jsonb:
    // command_risk_tier debe viajar aqui para llegar a honeypot_events.
    enrichment_data: {
      ...prevEnrichment,
      command_risk_tier: tier,
      vt_detections: vtDetections,
      domain_age_days: domainAgeDays,
      enrichment_timestamp: enrichmentTimestamp
    },
    vt_detections: vtDetections,
    domain_age_days: domainAgeDays,
    enrichment_timestamp: enrichmentTimestamp
  }
}];

